    "",
    "// app/layout.tsx exports:",
    "export const metadata = { title: { template: '%s | App', default: 'App' } };",
  ];
  return (
    <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      {tree.join('\n')}
    </pre>
  );
}

